          { "@type": "Question", "name": "How do I convert amps to watts?", "acceptedAnswer": { "@type": "Answer", "text": "For DC: Watts = Amps × Volts. For AC single-phase: Watts = PF × Amps × Volts. For AC three-phase line-to-line: Watts = √3 × PF × Amps × V(L-L). For line-to-neutral: Watts = 3 × PF × Amps × V(L-N)." } },
          { "@type": "Question", "name": "How many watts is 10 amps at 120V?", "acceptedAnswer": { "@type": "Answer", "text": "At 120V AC with unity PF, 10 amps = 1200W. With PF=0.95: 1140W. For DC: 10A × 120V = 1200W." } },
          { "@type": "Question", "name": "What is the 3-phase amps to watts formula?", "acceptedAnswer": { "@type": "Answer", "text": "Line-to-line: P = √3 × PF × I × V(L-L) ≈ 1.732 × PF × I × V. Line-to-neutral: P = 3 × PF × I × V(L-N)." } },
          { "@type": "Question", "name": "How do I convert amp hours to watt hours?", "acceptedAnswer": { "@type": "Answer", "text": "Watt-hours = Amp-hours × Voltage. A 100Ah 12V battery stores 100 × 12 = 1200Wh (1.2 kWh). For mAh: (mAh ÷ 1000) × V = Wh." } },
          { "@type": "Question", "name": "What are typical power factor values?", "acceptedAnswer": { "@type": "Answer", "text": "Resistive loads/heaters/incandescent: PF=1.0. Fluorescent lamps: PF=0.95. Synchronous motors: PF=0.9. Induction motors full load: PF=0.85. Induction motors no load: PF=0.35." } },
          { "@type": "Question", "name": "Can I convert amps to watts without voltage?", "acceptedAnswer": { "@type": "Answer", "text": "No. Amperes measure current flow while watts measure power. Power = Voltage × Current. Without voltage you cannot determine how much energy each unit of charge carries." } },
          { "@type": "Question", "name": "What is the difference between real power (W), apparent power (VA), and reactive power (VAR)?", "acceptedAnswer": { "@type": "Answer", "text": "Real Power (W) performs actual work. Apparent Power (VA) is total power drawn (V×I). Reactive Power (VAR) is stored/released by inductors/capacitors. S² = P² + Q², and PF = P ÷ S." } },
          { "@type": "Question", "name": "What is the 80% continuous load rule?", "acceptedAnswer": { "@type": "Answer", "text": "Per NEC 210.19/210.20 breakers should not exceed 80% for continuous loads (3+ hrs). A 20A breaker supports 16A continuous. At 120V: 16A × 120V = 1920W max continuous." } },
          { "@type": "Question", "name": "How do I convert milliamps (mA) to watt hours?", "acceptedAnswer": { "@type": "Answer", "text": "Amps = mA ÷ 1000. Then Wh = Amps × Volts × Hours. Example: 500mA at 5V for 2h = (0.5A × 5V × 2h) = 5Wh." } },
          { "@type": "Question", "name": "How do watts relate to amps?", "acceptedAnswer": { "@type": "Answer", "text": "Via Watt's Law: P(W) = I(A) × V(V). For AC add PF. Amps measure current flow rate; watts measure energy transfer rate. You can have high amps with low watts at low voltage." } }
        ]
