solar-watts-to-amps-calculator.schema:
{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      { "@type": "Question", "name": "How many amps does a 100 watt solar panel produce?", "acceptedAnswer": { "@type": "Answer", "text": "A 100 watt solar panel produces about 8.33 amps at 12 volts, 4.17 amps at 24 volts, and 2.08 amps at 48 volts before controller and wiring losses." } },
      { "@type": "Question", "name": "How many amps is 200 watts solar panel?", "acceptedAnswer": { "@type": "Answer", "text": "A 200 watt solar panel produces about 16.67 amps at 12 volts, 8.33 amps at 24 volts, and 4.17 amps at 48 volts before system losses." } },
      { "@type": "Question", "name": "Can watts be converted to amps?", "acceptedAnswer": { "@type": "Answer", "text": "Yes. Convert watts to amps by dividing watts by voltage. The formula is amps equals watts divided by volts." } },
      { "@type": "Question", "name": "How do I calculate solar panel amperage?", "acceptedAnswer": { "@type": "Answer", "text": "Calculate solar panel amperage with I equals P divided by V, where I is current in amps, P is solar panel wattage, and V is operating voltage." } }
    ]
  }

speaker-amp-power-calculator.schema:
{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      { "@type": "Question", "name": "How much amplifier power for speakers?", "acceptedAnswer": { "@type": "Answer", "text": "Use amplifier RMS power close to the speaker RMS rating at the same impedance. For normal use, choose 75% to 150% of the speaker RMS rating with clean gain settings." } },
      { "@type": "Question", "name": "How many speakers can a 4 channel amp power?", "acceptedAnswer": { "@type": "Answer", "text": "A 4 channel amp powers 4 speakers when each channel drives one speaker at the rated impedance. More speakers require a safe final impedance per channel." } },
      { "@type": "Question", "name": "How many speakers can a 400W amp power?", "acceptedAnswer": { "@type": "Answer", "text": "A 400W amp can power 4 speakers at about 100W each when the amplifier is rated 100W x 4 and the speaker impedance matches the amplifier rating." } },
      { "@type": "Question", "name": "What amp do I need for my speakers?", "acceptedAnswer": { "@type": "Answer", "text": "Choose an amplifier that matches speaker RMS watts, speaker impedance, channel count, and the supply current available from the power system." } },
      { "@type": "Question", "name": "What happens if amp is too powerful for speakers?", "acceptedAnswer": { "@type": "Answer", "text": "An amp that is too powerful can damage speakers when gain is too high or the signal clips. A larger clean amplifier can be safe when output is limited below the speaker RMS rating." } },
      { "@type": "Question", "name": "How do I calculate amp for speakers?", "acceptedAnswer": { "@type": "Answer", "text": "Calculate speaker amplifier supply current with A = W / (V x efficiency). A 500W amplifier on a 12V supply at 85% efficiency draws about 49A." } }
    ]
  }

