voltage-amps-watts-calculator.schema:
{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      { "@type": "Question", "name": "Can you calculate amps from watts?", "acceptedAnswer": { "@type": "Answer", "text": "Yes. Calculate amps from watts by dividing watts by volts for DC and unity power factor loads. For AC single phase, divide watts by volts times power factor." } },
      { "@type": "Question", "name": "What is the watt voltage amp formula?", "acceptedAnswer": { "@type": "Answer", "text": "The basic formula is watts equals volts times amps. Rearranged formulas are amps equals watts divided by volts and volts equals watts divided by amps." } },
      { "@type": "Question", "name": "How many amps is 10000 watts?", "acceptedAnswer": { "@type": "Answer", "text": "10000 watts equals 83.33 amps at 120 volts, 45.45 amps at 220 volts, and 41.67 amps at 240 volts for DC or power factor 1.00 loads." } },
      { "@type": "Question", "name": "How many watts is 5 volts 3 amps?", "acceptedAnswer": { "@type": "Answer", "text": "5 volts and 3 amps equals 15 watts using watts equals volts times amps." } }
    ]
  }

voltage-drop-calculator.schema:
{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is voltage drop in electrical wiring?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Voltage drop is the voltage lost as current flows through wire or cable resistance. A voltage drop calculator estimates that loss from amps, distance, conductor resistance, material, and circuit type."
        }
      },
      {
        "@type": "Question",
        "name": "How much voltage drop is allowed?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "A common design target is 3 percent for branch circuits and 5 percent total feeder plus branch circuit voltage drop. Local NEC, IEC, BS7671, CEC, or project rules can set different limits."
        }
      },
      {
        "@type": "Question",
        "name": "How do you calculate voltage drop over distance?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "For DC and single phase circuits, use voltage drop equals 2 times current times resistance per length times one-way length. For 3 phase, use square root of 3 times current times resistance per length times length."
        }
      },
      {
        "@type": "Question",
        "name": "Does wire size affect voltage drop?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. Larger wire size has lower resistance, so larger AWG or mm2 conductors reduce voltage drop, heating, and power loss over distance."
        }
      }
    ]
  }

wire-gauge-calculator.schema:
{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What gauge wire do I need?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Choose gauge wire from amps, voltage, distance, material, insulation temperature, conduit fill, and acceptable voltage drop. A wire gauge calculator converts those inputs into an AWG or sq mm wire size."
        }
      },
      {
        "@type": "Question",
        "name": "What size wire calculator should I use for distance?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Use a wire size calculator for distance when the run is long or the system is low voltage. Distance raises resistance and voltage drop, so 12V DC and 24V DC systems often need larger wire than short 120V or 240V AC circuits."
        }
      },
      {
        "@type": "Question",
        "name": "How much weight can 14 gauge wire hold?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "14 gauge wire has no universal safe hanging weight. Electrical wire is rated for current capacity, not lifting. Use the manufacturer's working load limit for mechanical support."
        }
      }
    ]
  }
